import React, { useEffect, useState } from 'react';
import {
  Button,
  FormActions,
  Input,
  Modal,
  MoneyInput,
  NumberInput,
  Select,
  TextArea,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type {
  CreateScenarioCostItemDto,
  CreateScenarioDto,
  SensitivityVariableDto,
} from '../../../services/fpc/types';
import { DEFAULT_SENSITIVITY_VARIABLES } from '../../../services/fpc/types';
import { resolveApiErrorMessage } from '../../../services/catalogUiSchemaService';
import styles from './ScenarioForm.module.css';

const TEST_ID = 'create-scenario-form';

export const SCENARIO_TYPE_OPTIONS = [
  { value: 'Base', label: 'Cơ sở (Base)' },
  { value: 'Conservative', label: 'Thận trọng (Downside)' },
  { value: 'Upside', label: 'Tăng trưởng (Upside)' },
];

type DriverRow = {
  code: string;
  name: string;
  unit: string;
  costCode?: string;
  amount: number;
};

function defaultPeriod(): { start: string; end: string } {
  const now = new Date();
  const y = now.getFullYear();
  return { start: `${y}-01-01`, end: `${y}-12-31` };
}

function toIsoDate(ymd: string, endOfDay = false): string {
  if (!ymd) return new Date().toISOString();
  return endOfDay ? `${ymd}T23:59:59.000Z` : `${ymd}T00:00:00.000Z`;
}

function toDriverRows(list: SensitivityVariableDto[]): DriverRow[] {
  return list
    .filter(v => v.isActive !== false)
    .slice()
    .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0) || a.code.localeCompare(b.code))
    .map(v => ({
      code: v.code,
      name: v.name,
      unit: v.unit || 'money',
      costCode: v.costCode,
      amount: v.defaultAmount ?? 0,
    }));
}

function fallbackDriverRows(): DriverRow[] {
  return toDriverRows(
    DEFAULT_SENSITIVITY_VARIABLES.map((v, i) => ({
      id: `fallback-${i}`,
      ...v,
    })),
  );
}

export type CreateScenarioFormModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSaved: () => void;
};

type FormState = {
  name: string;
  scenarioType: string;
  periodStart: string;
  periodEnd: string;
  totalBudget: number;
  summary: string;
  drivers: DriverRow[];
};

type FormErrors = Partial<Record<'name' | 'scenarioType' | 'periodStart' | 'periodEnd', string>>;

function emptyForm(drivers: DriverRow[]): FormState {
  const p = defaultPeriod();
  return {
    name: '',
    scenarioType: 'Base',
    periodStart: p.start,
    periodEnd: p.end,
    totalBudget: 0,
    summary: '',
    drivers,
  };
}

function buildCostItems(drivers: DriverRow[]): CreateScenarioCostItemDto[] {
  return drivers
    .filter(d => d.unit === 'money' && d.costCode && d.amount > 0)
    .map(d => ({
      costCode: d.costCode!,
      costCodeName: d.name,
      amount: d.amount,
    }));
}

function buildAssumptionsJson(drivers: DriverRow[]): string {
  return JSON.stringify({
    drivers: drivers.map(d => ({
      code: d.code,
      name: d.name,
      unit: d.unit,
      costCode: d.costCode,
      value: d.amount,
    })),
  });
}

const CreateScenarioFormModal: React.FC<CreateScenarioFormModalProps> = ({
  isOpen,
  onClose,
  onSaved,
}) => {
  const dispatch = useAppDispatch();
  const [form, setForm] = useState<FormState>(() => emptyForm(fallbackDriverRows()));
  const [errors, setErrors] = useState<FormErrors>({});
  const [submitting, setSubmitting] = useState(false);
  const [loadingDrivers, setLoadingDrivers] = useState(false);

  useEffect(() => {
    if (!isOpen) return;
    let cancelled = false;
    setErrors({});
    setSubmitting(false);
    setLoadingDrivers(true);
    setForm(emptyForm(fallbackDriverRows()));

    void (async () => {
      try {
        const list = await fpcService.getSensitivityVariableList();
        if (cancelled) return;
        const rows = list.length ? toDriverRows(list) : fallbackDriverRows();
        setForm(emptyForm(rows));
      } catch {
        if (!cancelled) setForm(emptyForm(fallbackDriverRows()));
      } finally {
        if (!cancelled) setLoadingDrivers(false);
      }
    })();

    return () => { cancelled = true; };
  }, [isOpen]);

  const setField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    setForm(f => ({ ...f, [key]: value }));
    if (key === 'name' || key === 'scenarioType' || key === 'periodStart' || key === 'periodEnd') {
      setErrors(e => ({ ...e, [key]: undefined }));
    }
  };

  const setDriverAmount = (code: string, amount: number) => {
    setForm(f => ({
      ...f,
      drivers: f.drivers.map(d => (d.code === code ? { ...d, amount } : d)),
    }));
  };

  const validate = (): boolean => {
    const next: FormErrors = {};
    if (!form.name.trim()) next.name = 'Nhập tên kịch bản';
    if (!form.scenarioType) next.scenarioType = 'Chọn loại kịch bản';
    if (!form.periodStart) next.periodStart = 'Chọn từ ngày';
    if (!form.periodEnd) next.periodEnd = 'Chọn đến ngày';
    if (form.periodStart && form.periodEnd && form.periodEnd < form.periodStart) {
      next.periodEnd = 'Đến ngày phải ≥ Từ ngày';
    }
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const buildDto = (): CreateScenarioDto => {
    const costItems = buildCostItems(form.drivers);
    const costSum = costItems.reduce((s, c) => s + c.amount, 0);
    return {
      name: form.name.trim(),
      scenarioType: form.scenarioType,
      periodStart: toIsoDate(form.periodStart),
      periodEnd: toIsoDate(form.periodEnd, true),
      totalBudget: form.totalBudget > 0 ? form.totalBudget : (costSum > 0 ? costSum : undefined),
      summary: form.summary.trim() || undefined,
      assumptionsJson: buildAssumptionsJson(form.drivers),
      costItems: costItems.length ? costItems : undefined,
    };
  };

  const handleSave = async (andRun: boolean) => {
    if (!validate()) return;
    setSubmitting(true);
    try {
      const created = await fpcService.createScenario(buildDto());
      if (andRun) {
        await fpcService.runScenario(created.id);
        dispatchAppToast(dispatch, {
          message: 'Đã tạo và chạy kịch bản',
          type: 'success',
        });
      } else {
        dispatchAppToast(dispatch, { message: 'Đã tạo kịch bản (nháp)', type: 'success' });
      }
      onSaved();
      onClose();
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: resolveApiErrorMessage(err, 'Lỗi khi lưu kịch bản'),
        type: 'error',
      });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Tạo kịch bản"
      size="lg"
      data-testid={`${TEST_ID}-modal`}
    >
      <div className={styles.formBody} data-testid={`${TEST_ID}-body`}>
        <div className={styles.formGrid}>
          <Input
            label="Tên kịch bản"
            required
            value={form.name}
            onChange={e => setField('name', e.target.value)}
            error={errors.name}
            placeholder="VD: Cơ sở 2026"
            data-testid={`${TEST_ID}-name`}
          />
          <Select
            label="Loại kịch bản"
            required
            value={form.scenarioType}
            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setField('scenarioType', e.target.value)}
            options={SCENARIO_TYPE_OPTIONS}
            error={errors.scenarioType}
            data-testid={`${TEST_ID}-type`}
          />
          <Input
            label="Từ ngày"
            type="date"
            required
            value={form.periodStart}
            onChange={e => setField('periodStart', e.target.value)}
            error={errors.periodStart}
            data-testid={`${TEST_ID}-from`}
          />
          <Input
            label="Đến ngày"
            type="date"
            required
            value={form.periodEnd}
            onChange={e => setField('periodEnd', e.target.value)}
            error={errors.periodEnd}
            data-testid={`${TEST_ID}-to`}
          />
          <div className={styles.fullWidth}>
            <MoneyInput
              label="Tổng ngân sách dự chi"
              value={form.totalBudget}
              onChange={v => setField('totalBudget', Number(v) || 0)}
              data-testid={`${TEST_ID}-budget`}
            />
          </div>
          <div className={styles.fullWidth}>
            <TextArea
              label="Tóm tắt"
              value={form.summary}
              onChange={e => setField('summary', e.target.value)}
              rows={2}
              placeholder="Ghi chú giả định (tuỳ chọn)"
              data-testid={`${TEST_ID}-summary`}
            />
          </div>
        </div>

        <div className={styles.sectionHint}>
          Biến nhạy cảm (mặc định từ danh mục) — chỉnh giá trị trước khi lưu
          {loadingDrivers ? ' · Đang tải…' : ''}
        </div>
        <div className={styles.tableWrap}>
          <table className={styles.varGrid} data-testid={`${TEST_ID}-driver-grid`}>
            <thead>
              <tr>
                <th>Biến</th>
                <th>Đơn vị</th>
                <th className={styles.colNum}>Giá trị</th>
              </tr>
            </thead>
            <tbody>
              {form.drivers.map(row => (
                <tr key={row.code} data-testid={`${TEST_ID}-driver-${row.code}`}>
                  <td>
                    <strong>{row.name}</strong>
                    <div className={styles.driverCode}>{row.code}</div>
                  </td>
                  <td>
                    {row.unit === 'percent' ? '%' : row.unit === 'days' ? 'ngày' : 'tiền'}
                  </td>
                  <td className={styles.colNum}>
                    {row.unit === 'money' ? (
                      <MoneyInput
                        label=""
                        value={row.amount}
                        onChange={v => setDriverAmount(row.code, Number(v) || 0)}
                        data-testid={`${TEST_ID}-amt-${row.code}`}
                      />
                    ) : (
                      <NumberInput
                        label=""
                        value={row.amount}
                        onChange={v => setDriverAmount(row.code, Number.isFinite(v) ? v : 0)}
                        data-testid={`${TEST_ID}-amt-${row.code}`}
                      />
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <FormActions align="end" className={styles.formActions}>
          <Button variant="secondary" onClick={onClose} disabled={submitting} data-testid={`${TEST_ID}-cancel`}>
            Hủy
          </Button>
          <Button
            variant="secondary"
            onClick={() => void handleSave(false)}
            disabled={submitting}
            data-testid={`${TEST_ID}-save-draft`}
          >
            Lưu nháp
          </Button>
          <Button
            variant="primary"
            onClick={() => void handleSave(true)}
            disabled={submitting}
            data-testid={`${TEST_ID}-save-run`}
          >
            {submitting ? 'Đang lưu…' : 'Lưu và chạy'}
          </Button>
        </FormActions>
      </div>
    </Modal>
  );
};

export default CreateScenarioFormModal;
