import React from 'react';
import {
  Button,
  Slideout,
} from '@linm-soft-org/linm-web-common-components';
import type { ScenarioResultDto } from '../../../services/fpc/types';
import { SCENARIO_TYPE_OPTIONS } from './CreateScenarioFormModal';
import styles from './ScenarioForm.module.css';

const TEST_ID = 'view-scenario-slideout';

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

function typeLabel(type: string): string {
  return SCENARIO_TYPE_OPTIONS.find(o => o.value === type)?.label ?? type;
}

function formatDate(iso?: string): string {
  if (!iso) return '—';
  const d = iso.slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) return iso;
  const [y, m, day] = d.split('-');
  return `${day}/${m}/${y}`;
}

export type ViewScenarioSlideoutProps = {
  scenario: ScenarioResultDto | null;
  onClose: () => void;
  onRun?: (id: string) => void;
  canManage?: boolean;
  running?: boolean;
};

const ViewScenarioSlideout: React.FC<ViewScenarioSlideoutProps> = ({
  scenario,
  onClose,
  onRun,
  canManage,
  running,
}) => {
  const isOpen = !!scenario;
  const costItems = scenario?.costItems ?? [];
  const sensitivity = scenario?.sensitivity;

  const footer = (
    <div className={styles.slideoutFooter}>
      {canManage && scenario && onRun && (
        <Button
          variant="primary"
          disabled={running || (scenario.status || '').toLowerCase() === 'running'}
          onClick={() => onRun(scenario.id)}
          data-testid={`${TEST_ID}-run`}
        >
          {running ? 'Đang chạy…' : 'Chạy lại'}
        </Button>
      )}
      <Button variant="secondary" onClick={onClose} data-testid={`${TEST_ID}-close`}>
        Đóng
      </Button>
    </div>
  );

  return (
    <Slideout
      isOpen={isOpen}
      onClose={onClose}
      title={scenario ? `Xem kịch bản · ${scenario.name}` : 'Xem kịch bản'}
      width="min(720px, 96vw)"
      customFooter={footer}
      data-testid={`${TEST_ID}-root`}
    >
      {scenario && (
        <div className={styles.slideoutBody} data-testid={`${TEST_ID}-body`}>
          <div className={styles.metaGrid}>
            <div>
              <div className={styles.metaLabel}>Loại</div>
              <div className={styles.metaValue}>{typeLabel(scenario.scenarioType)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Trạng thái</div>
              <div className={styles.metaValue}>{scenario.status || '—'}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Từ ngày</div>
              <div className={styles.metaValue}>{formatDate(scenario.periodStart)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Đến ngày</div>
              <div className={styles.metaValue}>{formatDate(scenario.periodEnd)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Tổng ngân sách</div>
              <div className={styles.metaValue}>{fCompact(scenario.totalBudget ?? 0)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Doanh thu dự kiến</div>
              <div className={styles.metaValue}>{fCompact(scenario.projectedRevenue ?? 0)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>EBITDA</div>
              <div className={styles.metaValue}>{fCompact(scenario.projectedEbitda ?? 0)}</div>
            </div>
            <div>
              <div className={styles.metaLabel}>Tiền cuối kỳ</div>
              <div className={styles.metaValue}>{fCompact(scenario.projectedCashBalance ?? 0)}</div>
            </div>
          </div>

          {scenario.summary && (
            <div className={styles.sectionBlock}>
              <div className={styles.sectionHint}>Tóm tắt</div>
              <p className={styles.summaryText}>{scenario.summary}</p>
            </div>
          )}

          <div className={styles.sectionBlock}>
            <div className={styles.sectionHint}>Biến / khoản mục ({costItems.length})</div>
            <div className={styles.tableWrap}>
              <table className={styles.varGrid} data-testid={`${TEST_ID}-cost-grid`}>
                <thead>
                  <tr>
                    <th>Mã</th>
                    <th>Tên</th>
                    <th className={styles.colNum}>Số tiền</th>
                  </tr>
                </thead>
                <tbody>
                  {costItems.length === 0 ? (
                    <tr>
                      <td colSpan={3} className={styles.emptyCell}>Không có khoản mục</td>
                    </tr>
                  ) : (
                    costItems.map(c => (
                      <tr key={c.id || c.costCode}>
                        <td><strong>{c.costCode}</strong></td>
                        <td>{c.costCodeName}</td>
                        <td className={styles.colNum}>{fCompact(c.amount)}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>

          {sensitivity && sensitivity.rows.length > 0 && (
            <div className={styles.sectionBlock}>
              <div className={styles.sectionHint}>
                Ma trận biến nhạy cảm · {sensitivity.rows.length} biến
              </div>
              <div className={styles.tableWrap}>
                <table className={styles.varGrid} data-testid={`${TEST_ID}-sens-grid`}>
                  <thead>
                    <tr>
                      <th>Biến</th>
                      {sensitivity.columns.map(col => (
                        <th key={col} className={styles.colNum}>
                          {col === 0 ? 'Base' : `${col > 0 ? '+' : ''}${col}%`}
                        </th>
                      ))}
                    </tr>
                  </thead>
                  <tbody>
                    {sensitivity.rows.map(row => (
                      <tr key={row.code}>
                        <td style={{ fontWeight: 500 }}>{row.label}</td>
                        {row.values.map((val, idx) => (
                          <td key={`${row.code}-${idx}`} className={styles.colNum}>
                            {row.unit === 'percent'
                              ? `${val.toLocaleString('vi-VN', { maximumFractionDigits: 1 })}%`
                              : row.unit === 'days'
                                ? `${Math.round(val)} ngày`
                                : fCompact(val)}
                          </td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      )}
    </Slideout>
  );
};

export default ViewScenarioSlideout;
